  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  font-size: 16px;
  color: #1a1a1a;
  background-color: #f8f9fa;
}

body {
  line-height: 1.6;
}

/* Skip Link */
.skip-link {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 1000;
}

.skip-link a {
  position: absolute;
  left: -9999px;
  padding: 1rem;
  background-color: #0066cc;
  color: white;
  text-decoration: none;
  border-radius: 0 0 4px 0;
  font-weight: 500;
}

.skip-link a:focus {
  left: 0;
  top: 0;
}

/* Container & Layout */
.container {
  max-width: 600px;
  margin: 0 auto;
  padding: 2rem 1rem;
}

.header {
  text-align: center;
  margin-bottom: 3rem;
  padding-bottom: 2rem;
  border-bottom: 2px solid #e0e0e0;
}

.header h1 {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
  color: #0066cc;
}

.subtitle {
  font-size: 1rem;
  color: #666;
  font-weight: 400;
}

main {
  background: white;
  border-radius: 8px;
  padding: 2rem;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
}

/* Form */
.quiz-form {
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

/* Form Field / Question Wrapper */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.form-field fieldset {
  border: none;
  padding: 1rem;
  background-color: #f8f9fa;
  border-radius: 6px;
  border-left: 4px solid #0066cc;
}

.form-field legend {
  padding: 0;
  margin-bottom: 0.5rem;
}

.question-title {
  font-size: 1.1rem;
  font-weight: 600;
  color: #1a1a1a;
  display: block;
}

/* Help Text */
.help-text {
  font-size: 0.9rem;
  color: #555;
  font-style: italic;
  margin: 0.5rem 0;
  padding: 0.75rem;
  background-color: white;
  border-radius: 4px;
  border-left: 3px solid #ffa500;
}

/* Options Container */
.options {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin-top: 1rem;
}

/* Individual Option */
.option {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
}

.option input[type="checkbox"] {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  margin-top: 2px;
  cursor: pointer;
  accent-color: #0066cc;
}

.option input[type="checkbox"]:focus-visible {
  outline: 2px solid #0066cc;
  outline-offset: 2px;
  border-radius: 2px;
}

.option label {
  cursor: pointer;
  flex: 1;
  padding: 0.5rem 0;
  color: #333;
  font-size: 0.95rem;
}

.option input[type="checkbox"]:hover + label {
  color: #0066cc;
}

.option input[type="checkbox"]:disabled + label {
  color: #999;
  cursor: not-allowed;
}

/* Form Actions */
.form-actions {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
  padding-top: 2rem;
  border-top: 1px solid #e0e0e0;
}

/* Button */
.btn-primary {
  padding: 0.875rem 2rem;
  font-size: 1rem;
  font-weight: 600;
  color: white;
  background-color: #0066cc;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s ease;
  min-width: 140px;
}

.btn-primary:hover:not(:disabled) {
  background-color: #0052a3;
  box-shadow: 0 4px 12px rgba(0, 102, 204, 0.3);
}

.btn-primary:focus-visible {
  outline: 2px solid #0066cc;
  outline-offset: 2px;
}

.btn-primary:active:not(:disabled) {
  transform: scale(0.98);
}

.btn-primary:disabled {
  background-color: #ccc;
  cursor: not-allowed;
  opacity: 0.6;
}

/* Result Message */
.result-message {
  margin-top: 1.5rem;
  padding: 1rem;
  border-radius: 6px;
  display: none;
  font-weight: 500;
}

.result-message.show {
  display: block;
}

.result-message.success {
  background-color: #d4edda;
  color: #155724;
  border: 1px solid #c3e6cb;
}

.result-message.error {
  background-color: #f8d7da;
  color: #721c24;
  border: 1px solid #f5c6cb;
}

/* Responsive Design */
@media (max-width: 640px) {
  .container {
    padding: 1rem;
  }

  .header {
    margin-bottom: 2rem;
  }

  .header h1 {
    font-size: 1.5rem;
  }

  main {
    padding: 1.5rem;
  }

  .quiz-form {
    gap: 1.5rem;
  }

  .form-field fieldset {
    padding: 0.75rem;
  }

  .option input[type="checkbox"] {
    width: 18px;
    height: 18px;
  }
}

/* Forced Colors Mode */
@media (forced-colors: active) {
  .form-field fieldset {
    border: 1px solid CanvasText;
  }

  .help-text {
    border-left-color: CanvasText;
  }

  .btn-primary {
    border: 2px solid CanvasText;
  }

  .result-message {
    border: 1px solid CanvasText;
  }
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
